item.content:encoded:
.elementor .elementor-element.elementor-element-b009868.elementor-arrows-yes .elementor-main-swiper,	
.elementor .elementor-element.elementor-element-b009868.elementor-arrows-yes .elementor-main-swiper {
    overflow: hidden!important;
    width: calc(100% - 0px);
}	


@media (max-width: 601px) {
html {
    overflow: auto!important;
}
html body div .ctanumber.pum-trigger{
	padding: 10px 20px!important;
	font-size: 12px!important;
}
html .elementor-1325 .elementor-element.elementor-element-2a5e865 > .elementor-shape-top svg,	
html .elementor-1325 .elementor-element.elementor-element-4d25d77 > .elementor-shape-bottom svg {
    height: auto!important;
}	
}	

.wpcf7 .wpcf7-form-control-wrap {
    position: relative;
}

.wpcf7 .wpcf7-form-control-wrap .wpcf7-not-valid-tip {
    position: absolute;
    top: 100%;
    left: 0;
    color: red;
    font-size: 12px;
    margin-top: 5px;
}
.ctanumb {
	width:50%;
	margin-left:190px;
}
label.pvlnam {
    color: black;
}
form.wpcf7-form.init {
    text-align: center;
}
div#pum_popup_title_10177 {
    display: none;
}
.wpcf7 form.sent .wpcf7-response-output {
    border-color: #ffffff;
}
.wpcf7 .wpcf7-response-output {
    margin-top: 10px;
    color: red;
    display: block;
}
  .pum-content.popmake-content form.wpcf7-form{display: flex; justify-content: flex-start; align-items: center;flex-wrap: wrap;}
.pum-content.popmake-content form.wpcf7-form .ctanumb { margin-left: 35px; margin-right: 20px; }
.pum-content.popmake-content form.wpcf7-form label.pvlnam{font-weight: 500;}
.pum-overlay .pum-container .pum-title{font-weight: 500;color: #F37234;}
.pum-content.popmake-content .wpcf7 form .wpcf7-response-output{width: 100%;margin:0 0 10px;}
.pum-content.popmake-content .wpcf7 form .wpcf7-response-output{text-align: center;border-width: 1px;margin-top:20px}
.pum-content.popmake-content .wpcf7 .wpcf7-form-control-wrap .wpcf7-not-valid-tip{top: 40px;}
.pum-content.popmake-content #success-message{margin-top:35px;text-align: center;width: 100%;}
.pum-content.popmake-content form.wpcf7-form p{margin-bottom:0;}
.pum-theme-10169 .pum-container, .pum-theme-lightbox .pum-container {border: 5px solid #ddd!important;padding: 35px!important;}

@media only screen and (max-width: 767px) {
.pum-content.popmake-content form.wpcf7-form p{margin-bottom:15px;}
.pum-overlay .pum-container .pum-title{font-size: 26px;}
.pum-content.popmake-content form.wpcf7-form .ctanumb { margin-left: 0; margin-right: 0; width: 100%; }
.wpcf7 .wpcf7-form-control-wrap .wpcf7-not-valid-tip{position: static;}
.pum-theme-10169 .pum-container, .pum-theme-lightbox .pum-container {padding:15px!important;}
}


.elementor-kit-87 h1 {
    color: #2B2B2B !important;
    font-family: "Poppins", Sans-serif;
    font-size: 48px;
    font-weight: 700;
    line-height: 58px;
}


.elementor-field-group .elementor-select-wrapper select * {
	color: #2B2B2B !important;
}

html body .mystickyelement-lists-wrap{
	display: none !important;
}


body .version_02 .elementor-container {
	max-width: 100%!important;
}

