0","bottom":"0","left":"0","isLinked":false},"padding_tablet":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false}},"elements":[{"id":"269d945","elType":"widget","settings":{"slides":[{"content":"Good school, caring teachers, extremely supportive staff who put in a lot of effort and the experience has been good for us. It’s always a partnership between Institutions and parents to give the best to children and has therefore worked well for us. keep up the good work teachers and thank you.","name":"Mohan Ramaswamy","title":"","image":{"url":"https://rainbowinternationalschool.in/wp-content/uploads/2022/09/rainbow-international-school-testimonials-mohan-ramaswamy.jpg","id":709,"alt":"","source":"library"},"_id":"5f49803"},{"content":"I will recommend this school as this school given up so much in terms of values and well organized.. It was first time I sent my daughter for outstation picnic and beyond expectations it was really very well organized and communication between teachers and parents are always welcome… Management and teachers give ears to share parents point of view!!","name":"Ruchi Verma","title":"","image":{"url":"https://rainbowinternationalschool.in/wp-content/uploads/2022/09/rainbow-international-school-testimonials-ruchi-verma.jpg","id":711,"alt":"","source":"library"},"_id":"60a1f7f"},{"content":"We are very Happy with the school… authorities and the management. Teachers are also nice n ensure all the kids get the required attention. Extra curricular activities are also looked after and appreciated.","name":"Ratish Pradhan","title":"","image":{"url":"https://rainbowinternationalschool.in/wp-content/uploads/2022/09/rainbow-international-school-testimonials-ratish-pradhan.jpg","id":710,"alt":"","source":"library"},"_id":"ba20b46"},{"content":"A Progressive School with Very Supportive Management. Teachers & Support staff are very cooperative. Most Importantly, even if there are any issues School always puts forward an issue resolving approach","name":"Alok Srivastava","title":"","image":{"url":"https://rainbowinternationalschool.in/wp-content/uploads/2022/09/rainbow-international-school-testimonials-alok-shrivastava.jpg","id":708,"alt":"","source":"library"},"_id":"7fd5cfe"},{"content":"Highly recommended school. Most lively atmosphere. The warmth in the school makes every child comfortable. Lot of extra efforts taken by the management to introduce practical activities for students to get exposed to real challenges in real life. Hygiene their forte .. Undoubtedly the best school in Thane.","name":"Anuja Pradhan","title":"","image":{"url":"https://rainbowinternationalschool.in/wp-content/uploads/2022/09/rainbow-international-school-homepage-testimonials-anuja-pradhan.jpg","id":696,"alt":"","source":"library"},"_id":"075bd49"},{"content":"The study pattern in rainbow is very well balanced between books & extra activity, I love to here from my 8 yrs son when he explains me everything he learnt this means he is enjoying which was not the case one year back when he was in another school. Great going rainbow teachers keep it up.","name":"Chandrasekhar Ella","title":"","image":{"url":"https://rainbowinternationalschool.in/wp-content/uploads/2022/09/rainbow-international-school-reviews-chandrasekhar-ella-1.jpg","id":700,"alt":"","source":"library"},"_id":"859cd1d"},{"content":"Great school… standard of teaching is of very high level…also give preference to personality development… sports day.. picnic… annual day… every event was owsome… well organised & very nicely presented and executed.","name":"Hemalata Nigudkar","title":"","image":{"url":"https://rainbowinternationalschool.in/wp-content/uploads/2022/09/rainbow-international-school-reviews-hemalata-nigudkar.jpg","id":702,"alt":"","source":"library"},"_id":"661622c"},{"content":"A school where the teachers care for the students like parents do… the place where every child gets equal opportunity & blossoms into a better version of themselves. Students love to come to school as there is never a dull moment… fun & learning go hand in hand 👍🏻👍🏻","name":"Amrapali Koonapareddy","title":"","image":{"url":"https://rainbowinternationalschool.in/wp-content/uploads/2022/09/rainbow-international-school-reviews-amrapali-koonapareddy.jpg","id":699,"alt":"","source":"library"},"_id":"1956dc3"},{"content":"My daughter Aarya goes to this school, it is a great school with amazing infrastructure, safety is the most important thing that they have. Teachers are very supportive. The most thing I like that they have their own organic farm where kids learn the things practically. So far very nice experience. My kid enjoy this schooling.","name":"Aarya Rahul Desai","title":"","image":{"url":"https://rainbowinternationalschool.in/wp-content/uploads/2022/09/rainbow-international-school-reviews-aarya-rahul-desai.jpg","id":698,"alt":"","source":"library"},"_id":"dce5780"},{"content":"I would highly recommend Rainbow International School without hesitation. There are so many options locally that it can be overwhelming to choose but RIS gave my child a stellar foundation plus a nurturing environment that made the school an extension of our family. To watch the excellent teachers at Rainbow International School in action is truly a sight!","name":"Dhaval Lodaya","title":"","image":{"url":"https://rainbowinternationalschool.in/wp-content/uploads/2022/09/rainbow-international-school-reviews-dhaval-lodaya.jpg","id":701,"alt":"","source":"library"},"_id":"2dea512"},{"content":"Went for inquiry session, wonderful infrastructure, strong security arrangement and lovely people to guide. Surely going ahead for admissions. Would strong recommend Rainbow International School.","name":"Ravi Thakur","title":"","image":{"url":"https://rainbowinternationalschool.in/wp-content/uploads/2022/09/rainbow-international-school-reviews-ravi-thakur.jpg","id":706,"alt":"","source":"library"},"_id":"cef7e4f"},{"content":"Hello…feeling privileged to share my view on this page. Just a word… Fantastic school. The teachers are Professional, caring and well organized.. infrastructure is outstanding. Children grow intellectually as well as in other co Curricular activities… teachers really care & truly want the best for a child…","name":"Surabhi Trivedi","title":"","image":{"url":"https://rainbowinternationalschool.in/wp-content/uploads/2022/09/rainbow-international-school-reviews-surabhi-trivedi.jpg","id":707,"alt":"","source":"library"},"_id":"6059bdd"},{"content":"Rainbow international School nurtures each child’s natural talents & intelligence to help them achieve their full potential, through Academic Excellence, Outstanding coaching for Sports, Best Infrastructure, Personal Attention and Holistic Development.","name":"Nikhil Ghavnalkar","title":"","image":{"url":"https://rainbowinternationalschool.in/wp-content/uploads/2022/09/rainbow-international-school-reviews-nikhil-ghavnalkar.jpg","id":705,"alt":"","source":"library"},"_id":"36068dc"},{"content":"The school works on nurturing the kids for all-round development & rather than just focusing on academics. Many events are held throughout the year to encourage students to develop their skills in the relevant domain. The school is affiliated with CBSE & maintain the utmost standard of education. Highly recommended school to choose from. Best school in thane.","name":"Aabhay Choudhary","title":"","image":{"url":"https://rainbowinternationalschool.in/wp-content/uploads/2022/09/rainbow-international-school-reviews-aabhay-choudhary.jpg","id":697,"alt":"","source":"library"},"_id":"e30a493"},{"content":"Awesome school to get Education from. All The teachers are very creative and super supportive. My son is happy studying in Rainbow International School. My school is in their Anand Nagar Branch.","name":"Netra Patil Chatterjee","title":"","image":{"url":"https://rainbowinternationalschool.in/wp-content/uploads/2022/09/rainbow-international-school-reviews-netra-patil-chatterjee.jpg","id":704,"alt":"","source":"library"},"_id":"b3a6e58"},{"content":"It’s a great educational establishment to entrust your kids too, with an excellent infrastructure and warm-hearted, friendly and cooperative staff. I will recommend Rainbow International School for you kids.","name":"Mark D’Souza","title":"","image":{"url":"https://rainbowinternationalschool.in/wp-content/uploads/2022/09/rainbow-international-school-reviews-mark-dsouza.jpg","id":703,"alt":"","source":"library"},"_id":"a0b1f27"}],"layout":"image_stacked","width":{"unit":"%","size":70,"sizes":[]},"width_tablet":{"unit":"%","size":90,"sizes":[]},"width_mobile":{"unit":"%","size":90,"sizes":[]},"show_arrows":"","content_gap":{"unit":"px","size":20,"sizes":[]},"content_color":"#000","content_typography_typography":"custom","content_typography_font_family":"Roboto","content_typography_font_weight":"400","name_color":"#F37335","name_typography_typography":"custom","name_typography_font_family":"Roboto Slab","name_typography_font_size":{"unit":"px","size":24,"sizes":[]},"name_typography_font_weight":"400","image_size":{"unit":"px","size":75,"sizes":[]},"arrows_size":{"unit":"px","size":47,"sizes":[]},"pagination_size":{"unit":"px","size":10,"sizes":[]},"pagination_color_inactive":"#7A7A7A","pagination_color":"#F37335","__globals__":{"content_color":"","content_typography_typography":"","name_typography_typography":"","pagination_color_inactive":""}},"elements":[],"widgetType":"testimonial-carousel"}],"isInner":false}]

